# recreate components and enumerate same edge align for corrected grid
from collections import deque
objs=[];seen=set();h,w=len(correct_test),len(correct_test[0])
for r in range(h):
 for c in range(w):
  col=correct_test[r][c]
  if not col or (r,c) in seen: continue
  q=deque([(r,c)]);seen.add((r,c));cells=[]
  while q:
   y,x=q.popleft();cells.append((y,x))
   for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
    ny,nx=y+dy,x+dx
    if 0<=ny<h and 0<=nx<w and (ny,nx) not in seen and correct_test[ny][nx]==col:
     seen.add((ny,nx));q.append((ny,nx))
  objs.append((col,cells,min(y for y,x in cells),max(y for y,x in cells)))
print([(o[0],len(o[1]),o[2],o[3],min(x for y,x in o[1]),max(x for y,x in o[1])) for o in objs])
from itertools import product
poss=[]
for choices in product((True,False),repeat=len(objs)):
 occupied=set();clashes=0; mass=[0,0]
 for ch,(col,cells,t,b) in zip(choices,objs):
  dy=-t if ch else h-1-b
  mass[not ch]+=len(cells)
  for y,x in cells:
